  add('account-search','SEARCH-EMPTY','No search results','Prompt to refine the archive query.','.search-empty','No matching pages','<div class="search-empty"><span>⌕</span><strong>No pages found</strong><p>Try a different word or a shorter phrase.</p></div>',{source:'app.js'});

  add('books-articles','BOOK-PANEL','Book panel & section tree','Elemental book heading and nested reference links.','.books-grid > .panel, .book-mark, .books-grid details','Five elemental book accents; nested Sections','<div class="workspace"><div class="books-grid"><section class="panel"><h2><svg class="book-mark" viewBox="0 0 32 34" fill="none" stroke="currentColor" aria-hidden="true"><path d="M4 12c4-6 8 6 12 0s8 6 12 0M4 19c4-6 8 6 12 0s8 6 12 0M4 26c4-6 8 6 12 0s8 6 12 0"/></svg><a href="#/book-of-water">Book of Water</a></h2><ul><li><a href="#/magic">Magic</a><details open><summary>Sections</summary><ul><li><a href="#/air-spells">Air spells</a></li></ul></details></li></ul></section></div></div>');
