  add('print','PRINT-IDENTITY','Print identity & title','Ruled identity and experience fields above the paper sheet.','.creator-print-sheet, .print-first-page, .print-sheet-body, .print-left, .print-right, .print-sheet-head, .print-line, .print-sheet-title','Name, clan, family, school, rank, XP, Insight',`<header class="print-sheet-head"><div class="print-head-identity">${printLine('Name','Doji Ren')}${printLine('Clan','Crane')}${printLine('Family','Doji')}</div><div class="print-head-ranks">${printLine('Rank','1')}${printLine('Experience Points','12')}${printLine('Insight','128')}</div><div class="print-sheet-title"><span class="print-five">◯ ◯<br>◯ ◯<br> ◯</span><strong>Legend of the<br>Five Rings</strong></div></header>`);
